1	import { log } from './logger.js';
2	import { closePopups } from './popups.js';
3	
4	/**
5	 * 抓取当前店铺（聚合「全球」视图）的监测指标：
6	 *   - onSaleCount          「在售中 N」数量（顶部状态 tab，beast-core-tab-itemLabel）
7	 *   - trafficWatchCount    「商品流量待关注」数量（点快速筛选 chip → 读「共有 N 条」）
8	 *   - trafficDeclineExists 是否存在「商品流量近期有下降」商品（用「批量处理流量下降商品」按钮存在性判断）
9	 *   - trafficAnomalyTotal  流量异常合计（当前 = 待关注数；下降无精确计数入口，单独用布尔信号告警）
10	 *
11	 * 说明：真实后台是 Temu 自研 beast-core UI 库，选择器优先用稳定的 data-testid。
12	 */
13	export async function scanStore(page, storeName, cfg) {
14	  // 确保在商品列表页
15	  if (!/goods\/list/.test(page.url())) {
16	    await page.goto(cfg.goodsListUrl, { waitUntil: 'commit' }).catch(() => {});
17	    await page.waitForTimeout(3000);
18	  }
19	  await closePopups(page);
20	  await waitGrid(page);
21	
22	  const onSaleCount = await readOnSaleCount(page);
23	  const { trafficWatchCount, trafficDeclineExists } = await readTraffic(page);
24	  const trafficAnomalyTotal = trafficWatchCount ?? 0;
25	
26	  return {
27	    store: storeName,
28	    onSaleCount,
29	    trafficWatchCount,
30	    trafficDeclineExists,
31	    trafficAnomalyTotal,
32	  };
33	}
34	
35	/** 等商品表格真正渲染出行 */
36	async function waitGrid(page) {
37	  await page
38	    .locator('[data-testid="beast-core-table-body-tr"]')
39	    .first()
40	    .waitFor({ state: 'visible', timeout: 20000 })
41	    .catch(() => {});
42	}
43	
44	/** 读「在售中 N」——tab 叶子文本形如「在售中 13」 */
45	async function readOnSaleCount(page) {
46	  const tabs = page.locator('[data-testid="beast-core-tab-itemLabel"]');
47	  const n = await tabs.count().catch(() => 0);
48	  for (let i = 0; i < n; i++) {
49	    const t = (await tabs.nth(i).innerText().catch(() => '')).trim();
50	    const m = t.match(/在售中\s*([\d,]+)/);
51	    if (m) return Number(m[1].replace(/,/g, ''));
52	  }
53	  // 兜底：纯文本匹配
54	  const loc = page.getByText(/在售中\s*[\d,]+/).first();
55	  const txt = await loc.innerText({ timeout: 2000 }).catch(() => '');
56	  const m = txt.match(/在售中\s*([\d,]+)/);
57	  return m ? Number(m[1].replace(/,/g, '')) : null;
58	}
59	
60	/** 读流量异常：点「商品流量待关注」筛选读计数 + 判「流量下降」是否存在 */
61	async function readTraffic(page) {
62	  let trafficWatchCount = null;
63	
