import { diffStore } from './src/state.js';
const cfg = { onSaleDrop:true, trafficAnomaly:true };
// 模拟上周真实序列：3 -> null(筛选失效) -> 3(恢复)
let prev = { onSaleCount:13, trafficWatchCount:3, trafficDeclineExists:true };
// run.js 的 carry 逻辑：null 轮沿用上次已知值
const carry = (cur,p,k)=> (cur==null && p && typeof p[k]==='number') ? p[k] : cur;

function step(name, result){
  const events = diffStore(prev, result, cfg);
  const watch = carry(result.trafficWatchCount, prev, 'trafficWatchCount');
  const onSale = carry(result.onSaleCount, prev, 'onSaleCount');
  console.log(name, '=> 告警:', events.length? events.map(e=>e.text).join('|') : '(无)');
  prev = { onSaleCount:onSale, trafficWatchCount:watch, trafficDeclineExists:result.trafficDeclineExists };
}
step('轮B 筛选失效null ', { onSaleCount:13, trafficWatchCount:null, trafficDeclineExists:true });
step('轮C 恢复读到3   ', { onSaleCount:13, trafficWatchCount:3,   trafficDeclineExists:true });
step('轮D 又失效null  ', { onSaleCount:13, trafficWatchCount:null, trafficDeclineExists:true });
step('轮E 恢复读到3   ', { onSaleCount:13, trafficWatchCount:3,   trafficDeclineExists:true });
console.log('--- 真实上升 3 -> 5 应当告警 ---');
step('轮F 真升到5     ', { onSaleCount:13, trafficWatchCount:5,   trafficDeclineExists:true });
